import{_ as e,o as r,c as a,a3 as c}from"./chunks/framework.DdpBa4_E.js";const D=JSON.parse('{"title":"在 Windows 和 Mac 中使用 Docker","description":"","frontmatter":{},"headers":[],"relativePath":"books/docker-guide/02-安装运行-在-Windows-和-Mac-中使用-Docker.md","filePath":"books/docker-guide/02-安装运行-在-Windows-和-Mac-中使用-Docker.md","lastUpdated":1784250840000}'),n={name:"books/docker-guide/02-安装运行-在-Windows-和-Mac-中使用-Docker.md"};function s(i,o,k,d,p,t){return r(),a("div",null,[...o[0]||(o[0]=[c(`<h1 id="在-windows-和-mac-中使用-docker" tabindex="-1">在 Windows 和 Mac 中使用 Docker <a class="header-anchor" href="#在-windows-和-mac-中使用-docker" aria-label="Permalink to &quot;在 Windows 和 Mac 中使用 Docker&quot;">​</a></h1><p>对于开发来说，Windows 和 macOS 是更为常见和常用的系统，所以也很有必要了解在 Windows 和 macOS 中使用 Docker 的方法。很幸运的是，Docker 的官方对这两个系统提供了强有力的支持，我们可以很轻松的在这两个系统中运行 Docker。在这一小节中，我们就来了解一下 Docker 在 Windows 和 macOS 中安装的方式以及运行的原理。</p><h2 id="docker-desktop" tabindex="-1">Docker Desktop <a class="header-anchor" href="#docker-desktop" aria-label="Permalink to &quot;Docker Desktop&quot;">​</a></h2><p>在大多数情况下，我们的开发工作是在 Windows 或 macOS 这两个操作系统中进行的，既然 Docker 是我们用来解决开发、测试到运维整条产品线的工具，自然支持这两个系统是不可或缺的功能。</p><p>如同封装 Docker 为我们提供了轻松的虚拟化运行环境一样，Docker 在 Windows 和 macOS 中的安装也是极易完成的。Docker 官方为 Windows 和 macOS 系统单独开辟了一条产品线，名为 Docker Desktop，其定位是快速为开发者提供在 Windows 和 macOS 中运行 Docker 环境的工具。</p><p>Docker Desktop 实现容器化与 Docker Engine 是一致的，这就保证了我们在 Windows 和 macOS 中开发所使用的环境可以很轻松的转移到其他的 Docker 实例中，不论这个 Docker 实例是运行在 Windows、macOS 亦或是 Linux。</p><p>Docker Desktop 产品线包含两个软件，也就是针对 Windows 系统的 Docker for Windows 和针对 macOS 的 Docker for Mac。</p><h3 id="安装-docker-desktop" tabindex="-1">安装 Docker Desktop <a class="header-anchor" href="#安装-docker-desktop" aria-label="Permalink to &quot;安装 Docker Desktop&quot;">​</a></h3><p>在安装 Docker for Windows 和 Docker for Mac 之前，我们依然要了解一下两款软件对操作系统及软硬件的要求，只有达到了这些要求，我们才能顺利的安装上 Docker for Windows 和 Docker for Mac。</p><p>对于 Windows 系统来说，安装 Docker for Windows 需要符合以下条件：</p><ul><li>必须使用 Windows 10 Pro ( 专业版 )</li><li>必须使用 64 bit 版本的 Windows</li></ul><p>对于 macOS 系统来说，安装 Docker for Mac 需要符合以下条件：</p><ul><li>Mac 硬件必须为 2010 年以后的型号</li><li>必须使用 macOS El Capitan 10.11 及以后的版本</li></ul><p>另外，虚拟机软件 VirtualBox 与 Docker Desktop 兼容性不佳，建议在安装 Docker for Windows 和 Docker for Mac 之前先卸载 VirtualBox。</p><p>在确认系统能够支持 Docker Desktop 之后，我们就从 Docker 官方网站下载这两个软件的安装程序，这里直接附上 Docker Store 的下载链接，供大家直接下载：</p><ul><li><a href="https://store.docker.com/editions/community/docker-ce-desktop-windows" target="_blank" rel="noreferrer">Docker for Windows</a> ( <a href="https://store.docker.com/editions/community/docker-ce-desktop-windows" target="_blank" rel="noreferrer">https://store.docker.com/editions/community/docker-ce-desktop-windows</a> )</li><li><a href="https://store.docker.com/editions/community/docker-ce-desktop-mac" target="_blank" rel="noreferrer">Docker for Mac</a> ( <a href="https://store.docker.com/editions/community/docker-ce-desktop-mac" target="_blank" rel="noreferrer">https://store.docker.com/editions/community/docker-ce-desktop-mac</a> )</li></ul><p>安装 Docker for Windows 和 Docker for Mac 的方法十分简单，按 Windows 或 macOS 常见的软件安装方式安装即可。</p><h3 id="启动-docker" tabindex="-1">启动 Docker <a class="header-anchor" href="#启动-docker" aria-label="Permalink to &quot;启动 Docker&quot;">​</a></h3><p>像 Linux 中一样，我们要在 Windows 和 macOS 中使用 Docker 前，我们需要先将 Docker 服务启动起来。在这两个系统中，我们需要启动的就是刚才我们安装的 Docker for Windows 和 Docker for Mac 了。</p><p>启动两个软件的方式很简单，我们只需要通过操作系统的快捷访问功能查找到 Docker for Windows 或 Docker for Mac 并启动即可。</p><p>打开软件之后，我们会在 Windows 的任务栏或者 macOS 的状态栏中看到 Docker 的大鲸鱼图标。</p><p><img src="https://user-gold-cdn.xitu.io/2018/9/10/165c1d1fb7030b63?w=1186&amp;h=431&amp;f=png&amp;s=92607" alt="" loading="lazy"></p><p>Docker for Windows 或 Docker for Mac 在启动时，这只大鲸鱼上的集装箱会一直闪动，这说明 Docker 程序正在部署 docker daemon 所需要的一些环境并执行 docker daemon 的启动。当集装箱不再闪动，就说明 Docker 服务已经准备就绪，我们就可以在 Windows 和 macOS 中使用 Docker 了。</p><p>Docker Desktop 为我们在 Windows 和 macOS 中使用 Docker 提供了与 Linux 中几乎一致的方法，我们只需要打开 Windows 中的 PowerShell 获得 macOS 中的 Terminal，亦或者 Git Bash、Cmder、iTerm 等控制台类软件，输入 <code>docker</code> 命令即可。</p><p>使用 <code>docker version</code> 能够看到 Docker 客户端的信息，我们可以在这里发现程序运行的平台：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>λ docker version</span></span>
<span class="line"><span>Client:</span></span>
<span class="line"><span>## ......</span></span>
<span class="line"><span> OS/Arch:  windows/amd64</span></span>
<span class="line"><span>## ......</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="docker-desktop-的实现原理" tabindex="-1">Docker Desktop 的实现原理 <a class="header-anchor" href="#docker-desktop-的实现原理" aria-label="Permalink to &quot;Docker Desktop 的实现原理&quot;">​</a></h2><p>通过之前小节的介绍，我们知道 Docker 的核心功能，也就是容器实现，是基于 Linux 内核中 Namespaces、CGroups 等功能的。那么大体上可以说，Docker 是依赖于 Linux 而存在的。那么问题来了，Docker Desktop 是如何实现让我们在 Windows 和 macOS 中如此顺畅的使用 Docker 的呢？</p><p>其实 Docker Desktop 的实现逻辑很简单：既然 Windows 和 macOS 中没有 Docker 能够利用的 Linux 环境，那么我们生造一个 Linux 环境就行啦！Docker for Windows 和 Docker for Mac 正是这么实现的。</p><p>由于虚拟化在云计算时代的广泛使用，Windows 和 MacOS 也将虚拟化引入到了系统本身的实现中，这其中就包含了之前我们所提到的通过 Hypervisor 实现虚拟化的功能。在 Windows 中，我们可以通过 Hyper-V 实现虚拟化，而在 macOS 中，我们可以通过 HyperKit 实现虚拟化。</p><p>Docker for Windows 和 Docker for Mac 这里利用了这两个操作系统提供的功能来搭建一个虚拟 Linux 系统，并在其之上安装和运行 docker daemon。</p><p><img src="https://user-gold-cdn.xitu.io/2018/9/12/165cb3b94b24b951?w=1374&amp;h=517&amp;f=png&amp;s=51096" alt="" loading="lazy"></p><p>除了搭建 Linux 系统并运行 docker daemon 之外，Docker Desktop 系列最突出的一项功能就是我们能够直接通过 PowerShell、Terminal 这类的控制台软件在 Windows 和 macOS 中直接操作虚拟 Linux 系统中运行的 docker daemon。</p><p>实现这个功能得益于 docker daemon 对外提供的操作过程并不是复杂且领域性强的 IPC 等方式，而是通用的 RESTful Api 的形式。也就是说，Docker Desktop 只要实现 Windows 和 macOS 中的客户端，就能够直接利用 Hypervisor 的网络支持与虚拟 Linux 系统中的 docker daemon 进行通讯，并对它进行控制。</p><p>这其实就是我们之前所提到 docker daemon 使用 RESTful Api 作为控制方式的优势体现了。</p><h3 id="主机文件挂载" tabindex="-1">主机文件挂载 <a class="header-anchor" href="#主机文件挂载" aria-label="Permalink to &quot;主机文件挂载&quot;">​</a></h3><p>控制能够直接在主机操作系统中进行，给我们使用 Docker Desktop 系列软件提供了极大的方便。除此之外，文件的挂载也是 Docker Desktop 所提供的大幅简化我们工作效率且简化使用的功能之一。</p><p>之前我们谈到了，Docker 容器中能够通过数据卷的方式挂载宿主操作系统中的文件或目录，宿主操作系统在 Windows 和 macOS 环境下的 Docker Desktop 中，指的是虚拟的 Linux 系统。</p><p>当然，如果只能从虚拟的 Linux 系统中进行挂载，显然不足以达到我们的期望，因为最方便的方式必然是直接从 Windows 和 macOS 里挂载文件了。</p><p>要实现我们所期望的效果，也就是 Docker 容器直接挂载主机系统的目录，我们可以先将目录挂载到虚拟 Linux 系统上，再利用 Docker 挂载到容器之中。这个过程被集成在了 Docker Desktop 系列软件中，我们不需要人工进行任何操作，整个过程已经实现了自动化。</p><p><img src="https://user-gold-cdn.xitu.io/2018/9/11/165c8400bf8f809e?w=1491&amp;h=832&amp;f=png&amp;s=97059" alt="" loading="lazy"></p><p>Docker Desktop 对 Windows 和 macOS 到虚拟 Linux 系统，再到 Docker 容器中的挂载进行了实现，我们只需要直接选择能够被挂载的主机目录 ( 这个过程更多也是为了安全所考虑 )，剩下的过程全部由 Docker Desktop 代替我们完成。这相比于普通虚拟机软件进行挂载的过程来说，完全不能用百倍效率来比较了。</p><h2 id="配置-docker-desktop" tabindex="-1">配置 Docker Desktop <a class="header-anchor" href="#配置-docker-desktop" aria-label="Permalink to &quot;配置 Docker Desktop&quot;">​</a></h2><p>在我们使用 Docker Desktop 系列之前，我们还会简单修改其的一些配置，以便更好的合理搭配操作系统与 Docker Desktop 系列软件。</p><p>我们可以通过 Docker for Windows 或 Docker for Mac 的大鲸鱼图标打开配置页面：在大鲸鱼弹出的菜单中选择 Settings ( Windows ) 或 Preferences ( macOS )。</p><p>打开 Docker for Windows 和 Docker for Mac 的配置页面后，我们可以发现几个配置页面。这里我不逐一把每个页面进行截图了，大家可以自己动手查看页面每个页面的内容。</p><p><img src="https://user-gold-cdn.xitu.io/2018/9/11/165c62cd575bb4e8?w=1559&amp;h=614&amp;f=png&amp;s=339615" alt="" loading="lazy"></p><p>Docker for Windows 和 Docker for Mac 的配置项目较 Docker Engine 来说要多上许多，这主要是因为 Docker Desktop 是 Docker Engine 的超集，所以其不仅包含了 Docker Engine 的配置内容，还要包含诸如虚拟机实现等其他配置。</p><p>我这里抽出几个与 Docker 相关的关键配置，分别简单说明它们的作用：</p><h4 id="文件系统挂载配置" tabindex="-1">文件系统挂载配置 <a class="header-anchor" href="#文件系统挂载配置" aria-label="Permalink to &quot;文件系统挂载配置&quot;">​</a></h4><p>在 Docker for Windows 的 Shared Drivers 面板，以及在 Docker for Mac 中的 File Sharing 面板中，包含了我们之前提到的将本机目录挂载到 Hypervisor 里 Linux 系统中的配置。</p><h4 id="资源控制配置" tabindex="-1">资源控制配置 <a class="header-anchor" href="#资源控制配置" aria-label="Permalink to &quot;资源控制配置&quot;">​</a></h4><p>在 Advanced 面板中，我们可以调整 Docker 最大占用的本机资源。当然，更准确的说我们是在调整虚拟 Linux 环境所能占用的资源，是通过这个方式影响 Docker 所能占用的最大资源。</p><h4 id="网络配置" tabindex="-1">网络配置 <a class="header-anchor" href="#网络配置" aria-label="Permalink to &quot;网络配置&quot;">​</a></h4><p>在 Docker for Windows 的 Network 面板，以及在 Docker for Mac 中的 Advanced 面板中，我们可以配置 Docker 内部默认网络的子网等内容。这个网络的作用以及更详细的内容，我们会在之第 9 节中进行讲解。</p><h4 id="docker-daemon-配置" tabindex="-1">docker daemon 配置 <a class="header-anchor" href="#docker-daemon-配置" aria-label="Permalink to &quot;docker daemon 配置&quot;">​</a></h4><p>在 Daemon 面板里，我们可以直接配置对 docker daemon 的运行配置进行调整。默认情况下，在 Daemon 面板里只有 Insecure registries 和 Registry mirrors 两个配置，分别用来定义未认证镜像仓库地址和镜像源地址。</p><p>我们可以点击切换按钮切换到 Advanced 模式，在这个模式下，我们可以直接编辑 docker daemon 的 daemon.json 配置文件，实现更具体、完整的配置 docker daemon 的目的。</p><h2 id="低系统版本解决方案" tabindex="-1">低系统版本解决方案 <a class="header-anchor" href="#低系统版本解决方案" aria-label="Permalink to &quot;低系统版本解决方案&quot;">​</a></h2><p>Docker Desktop 系列为我们在 Windows 和 macOS 中使用 Docker 提供了巨大的便利，几乎让我们可以在数分钟内搭建 Windows 和 macOS 中 Docker 的运行环境，并得到像 Linux 中使用 Docker 一样的体验。但 Docker Desktop 依然存在一定的局限性，其中最大的莫过于其对 Windows 和 macOS 的苛刻要求。虽然我们提倡保持操作系统的更新换代，以得到最新的功能以及更好的安全保障，但依然有很多情况下我们不得不使用低版本的 Windows 和 macOS。对于这种情况，Docker 官方也提供了相应的解决方案。</p><p>首先，让我们来聊聊为什么 Docker for Windows 和 Docker for Mac 会对操作系统有如此严苛的要求。其实原因很简单，刚才我们谈到了，Docker for Windows 和 Docker for Mac 的实现分别依靠了 Windows 中的 Hyper-V 和 macOS 中的 HyperKit，而这两个虚拟化工具只在高版本的 Windows 和 macOS 系统中才提供出来。</p><p>既然知道了原因，解决方案自然也就有了，既然我们不能利用 Hyper-V 或 HyperKit 来创建虚拟的 Linux 系统，那就找一个能够替代它们的工具，用其创建虚拟 Linux 系统即可。</p><h3 id="docker-toolbox" tabindex="-1">Docker Toolbox <a class="header-anchor" href="#docker-toolbox" aria-label="Permalink to &quot;Docker Toolbox&quot;">​</a></h3><p>Docker 官方为我们找到了用于搭建虚拟 Linux 系统的软件，即 Oracle 的 VirtualBox，并以此封装了另一个集成的 Docker 运行环境软件：Docker Toolbox。</p><p>安装 Docker Toolbox 的过程也十分简单，下载安装包并按常规软件一样安装即可。这里直接我直接提供给大家 Docker Toolbox 安装包的连接，方便大家下载。</p><ul><li><a href="https://download.docker.com/win/stable/DockerToolbox.exe" target="_blank" rel="noreferrer">Docker Toolbox for Windows</a> ( <a href="https://download.docker.com/win/stable/DockerToolbox.exe" target="_blank" rel="noreferrer">https://download.docker.com/win/stable/DockerToolbox.exe</a> )</li><li><a href="https://download.docker.com/mac/stable/DockerToolbox.pkg" target="_blank" rel="noreferrer">Docker Toolbox for Mac</a> ( <a href="https://download.docker.com/mac/stable/DockerToolbox.pkg" target="_blank" rel="noreferrer">https://download.docker.com/mac/stable/DockerToolbox.pkg</a> )</li></ul><p>安装完 Docker Toolbox 后，我们有几项与 Docker for Windows 和 Docker for Mac 不同的使用方法需要注意。</p><p>由于不能很好的与系统以及 VirtualBox 互通结合，我们启动、关闭、重启 Docker 服务不能完全实现自动化，所以这里 Docker 为我们提供了 Docker QuickStart Terminal 这个工具来处理这些过程。换个方式说，我们必须通过它来启动和操作 Docker，而不能再直接使用 PowerShell、Terminal 这类软件了。</p><p>另外一个不便之处就是文件系统的挂载，由于 Docker Toolbox 无法直接操作 VirtualBox 实现挂载，所以这个过程需要我们人工来进行。整个挂载的方式与我们之前谈到的一样，区别只是需要我们手动操作。将本机目录挂载到虚拟 Linux 系统中的配置在 VirtualBox 的 Settings 中，我们将本机需要挂载的目录配置进去并保存即可。</p><h2 id="留言互动" tabindex="-1">留言互动 <a class="header-anchor" href="#留言互动" aria-label="Permalink to &quot;留言互动&quot;">​</a></h2><p>在这节中，在这一小节中我们掌握了如何在 Windows 和 macOS 安装 Docker Desktop 并进行配置，了解了 Docker Desktop 的实现原理。这里给大家留一道思考题：</p><blockquote><p>除了在 Windows 或 macOS 中搭建虚拟的 Linux 系统来实现基于 Linux Container 运行 Docker 这种方式外，你是否还知道直接使用 Windows 或 macOS 本身的容器技术运行 Docker 的方法？尝试了解这些实现方式，说说它们背后的原理。</p></blockquote><p>欢迎大家通过留言的方式说出你的看法。我会选出有代表性的优质留言，推荐给大家。</p><p>同时，如果你对 Docker Desktop 的安装、配置还有内部实现还有什么不解，可以加入到这本小册的官方微信群中，参与对相关问题的讨论。</p>`,74)])])}const m=e(n,[["render",s]]);export{D as __pageData,m as default};
